int singleNumber(int* nums, int numsSize) {
    int r = 0;
    for (int i = 0; i < numsSize; i++) r ^= nums[i];
    return r;
}

struct ListNode* reverseList(struct ListNode* head) {
    struct ListNode *p = NULL, *c = head;
    while (c) { struct ListNode* n = c->next; c->next = p; p = c; c = n; }
    return p;
}
